import moment from 'moment-timezone'
import dayjs from '../../src'
import utc from '../../src/plugin/utc'
import timezone from '../../src/plugin/timezone'

dayjs.extend(utc)
dayjs.extend(timezone)

const zones = ['America/New_York', 'America/Los_Angeles', 'Europe/London', 'Asia/Tokyo', 'Asia/Kolkata', 'Australia/Sydney', 'UTC', 'Pacific/Auckland']
const inputs = [
  '2013-02-08T09:30:26',
  '2013-02-08T09:30:26.123',
  '2013-02-08 09:30:26',
  '2014-06-01T12:00:00Z',
  '2014-06-01 12:00',
  '2014-06-01',
  '2012-03-11 02:30:00',
  '2012-11-04 01:30:00',
  1360306800000,
  1360306800123,
  new Date(1360306800000),
  new Date(1360306800123),
  dayjs(1360306800000),
  dayjs(1360306800123)
]

it('explore', () => {
  const report = []
  inputs.forEach((input) => {
    zones.forEach((zone) => {
      const label = `${String(input)} | ${zone}`
      let d; let m
      try { d = dayjs.tz(input, zone) } catch (e) { report.push(`THROW dayjs.tz(${label}): ${e.message}`); return }
      try { m = moment.tz(input, zone) } catch (e) { report.push(`THROW moment.tz(${label}): ${e.message}`); return }
      const checks = [
        ['format', d.format(), m.format()],
        ['formatZ', d.format('Z'), m.format('Z')],
        ['formatZZ', d.format('ZZ'), m.format('ZZ')],
        ['formatZZZ', d.format('ZZZ'), m.format('ZZZ')],
        ['valueOf', d.valueOf(), m.valueOf()],
        ['utcOffset', d.utcOffset(), m.utcOffset()],
        ['format_ha', d.format('ha'), m.format('ha')],
        ['isValid', d.isValid(), m.isValid()]
      ]
      checks.forEach(([name, a, b]) => {
        if (String(a) !== String(b)) report.push(`MISMATCH ${name} ${label}: dayjs=${a} moment=${b}`)
      })
      // also test .tz() conversion from an existing instance
      const d2 = dayjs(input).tz(zone)
      const m2 = moment(input).tz(zone)
      if (d2.format() !== m2.format()) report.push(`MISMATCH convert format ${label}: dayjs=${d2.format()} moment=${m2.format()}`)
      if (d2.format('Z') !== m2.format('Z')) report.push(`MISMATCH convert formatZ ${label}: dayjs=${d2.format('Z')} moment=${m2.format('Z')}`)
      if (d2.valueOf() !== m2.valueOf()) report.push(`MISMATCH convert valueOf ${label}: dayjs=${d2.valueOf()} moment=${m2.valueOf()}`)
      if (d2.utcOffset() !== m2.utcOffset()) report.push(`MISMATCH convert utcOffset ${label}: dayjs=${d2.utcOffset()} moment=${m2.utcOffset()}`)
    })
  })
  console.log(`\n=====REPORT START=====\n${report.join('\n')}\n=====REPORT END===== total mismatches: ${report.length}\n`)
  expect(true).toBe(true)
})

